1	package org.springframework.samples.petclinic.mapper;
2	
3	/**
4	 * Derives the owner's check digit: a single Luhn check digit (0-9) computed over the
5	 * digits contained in the customerCode. Non-digit characters are ignored. The value is a
6	 * pure function of the customerCode, so it needs no stored state.
7	 */
8	public final class CheckDigit {
9	
10	    private CheckDigit() {
11	    }
12	
13	    public static int of(String customerCode) {
14	        int sum = 0;
15	        boolean dbl = true;
16	        for (int i = customerCode.length() - 1; i >= 0; i--) {
17	            char c = customerCode.charAt(i);
18	            if (c < '0' || c > '9') {
19	                continue;
20	            }
21	            int d = c - '0';
22	            if (dbl) {
23	                d *= 2;
24	                if (d > 9) {
25	                    d -= 9;
26	                }
27	            }
28	            sum += d;
29	            dbl = !dbl;
30	        }
31	        return (10 - (sum % 10)) % 10;
32	    }
33	}
