1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Derives the single duplicate-detection key for an owner: the SHA-256 hex of
9	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners
10	 * are duplicates only when their whole identity keys match. Because the telephone is part
11	 * of the key, two members of one household with different telephones get different keys
12	 * and are both allowed; only an exact full-key match is a duplicate.
13	 */
14	public final class IdentityKey {
15	
16	    private IdentityKey() {
17	    }
18	
19	    public static String of(String telephone, String email, String lastName) {
20	        String key = (telephone == null ? "" : telephone) + "|"
21	                + (email == null ? "" : email.toLowerCase()) + "|" + Soundex.of(lastName);
22	        try {
23	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
24	            StringBuilder sb = new StringBuilder(digest.length * 2);
25	            for (byte b : digest) {
26	                sb.append(String.format("%02x", b));
27	            }
28	            return sb.toString();
29	        } catch (NoSuchAlgorithmException e) {
30	            throw new IllegalStateException(e);
31	        }
32	    }
33	}
