1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Fiscal-year helpers. The fiscal year starts on 1 July, so a date in July–December
7	 * belongs to the fiscal year of the following calendar year. Derived values are taken
8	 * from the (already business-day-adjusted) registration date.
9	 */
10	public final class FiscalYear {
11	
12	    private FiscalYear() {
13	    }
14	
15	    /** The four-digit fiscal year containing {@code date} (July–December roll into the next year). */
16	    public static int of(LocalDate date) {
17	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
18	    }
19	
20	    /** The fiscal year formatted {@code FY<YY>} (last two digits). */
21	    public static String label(LocalDate date) {
22	        return String.format("FY%02d", of(date) % 100);
23	    }
24	}
