1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Set;
4	
5	/**
6	 * Derives the owner's segment, formatted {@code <TIER>_<AREA>}. TIER is
7	 * {@code PREMIUM} when the membership level is 3 or more, otherwise {@code STANDARD}.
8	 * AREA is {@code METRO} when the locality is a known region (NSW, VIC or QLD),
9	 * otherwise {@code REGIONAL}. The value is a pure function of level and locality.
10	 */
11	public final class OwnerSegment {
12	
13	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
14	
15	    private OwnerSegment() {
16	    }
17	
18	    public static String of(int membershipLevel, String locality) {
19	        String tier = membershipLevel >= 3 ? "PREMIUM" : "STANDARD";
20	        String area = METRO_REGIONS.contains(locality) ? "METRO" : "REGIONAL";
21	        return tier + "_" + area;
22	    }
23	}
