1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives the owner's locality (region). The postcode is preferred: a 4-digit
7	 * postcode is mapped to its region by range (NSW 2000-2099, VIC 3000-3099,
8	 * QLD 4000-4099). When the postcode is absent or falls in no known range, it
9	 * falls back to a fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
10	 * Brisbane->QLD), or {@code UNKNOWN} when the city is not in the table. The value
11	 * is a pure function of postcode and city, so it needs no stored state.
12	 */
13	public final class Locality {
14	
15	    private static final Map<String, String> CITY_REGION = Map.of(
16	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
17	
18	    private static final Map<String, int[]> REGION_RANGE = Map.of(
19	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
20	
21	    private Locality() {
22	    }
23	
24	    public static String of(String city) {
25	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
26	    }
27	
28	    public static String of(String postcode, String city) {
29	        String byPostcode = byPostcode(postcode);
30	        return byPostcode != null ? byPostcode : of(city);
31	    }
32	
33	    private static String byPostcode(String postcode) {
34	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
35	            return null;
36	        }
37	        int value = Integer.parseInt(postcode);
38	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
39	            int[] range = entry.getValue();
40	            if (value >= range[0] && value <= range[1]) {
41	                return entry.getKey();
42	            }
43	        }
44	        return null;
45	    }
46	}
