1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashSet;
4	import java.util.Set;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Ensures the assigned {@code customerCode} is unique. When it collides with an existing
12	 * owner's code, appends {@code -<n>} with the smallest {@code n} of 2 or more that makes
13	 * it unique. Runs before the new owner is saved, so it compares against pre-existing owners.
14	 */
15	public class DeduplicateCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        Set<String> taken = new HashSet<>();
19	        for (Owner existing : ownerRepository.findAll()) {
20	            taken.add(existing.getCustomerCode());
21	        }
22	        String base = owner.getCustomerCode();
23	        String candidate = base;
24	        for (int n = 2; taken.contains(candidate); n++) {
25	            candidate = base + "-" + n;
26	        }
27	        owner.setCustomerCode(candidate);
28	    }
29	}
