1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.mapstruct.AfterMapping;
4	import org.mapstruct.MappingTarget;
5	import org.springframework.beans.factory.annotation.Autowired;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.function.owner.HouseholdTier;
10	import org.springframework.stereotype.Component;
11	
12	/**
13	 * Fills the derived {@code membershipPoints} and {@code membershipLevel} on every owner
14	 * DTO. It needs the {@link OwnerRepository} to size the household, so it runs as a
15	 * MapStruct {@code @AfterMapping} step wired into {@code OwnerMapper} rather than as a
16	 * static expression.
17	 */
18	@Component
19	public class MembershipDecorator {
20	
21	    @Autowired
22	    private OwnerRepository ownerRepository;
23	
24	    @AfterMapping
25	    public void addMembership(Owner owner, @MappingTarget OwnerDto dto) {
26	        boolean goldHousehold = HouseholdTier.isGold(owner, ownerRepository);
27	        int points = MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(),
28	                owner.getRegistrationDate(), goldHousehold);
29	        dto.setMembershipPoints(points);
30	        dto.setMembershipLevel(HouseholdCap.cap(owner, MembershipLevel.of(points), ownerRepository));
31	        dto.setOwnerSegment(OwnerSegment.of(dto.getMembershipLevel(), dto.getLocality()));
32	    }
33	}
