15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = {PetMapper.class, MembershipDecorator.class})
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "salutation", expression = "java(owner.getTitle() == null || owner.getTitle().isBlank() ? owner.getLastName() : owner.getTitle() + \" \" + owner.getLastName())")
23	    @Mapping(target = "telephoneDisplay", expression = "java(TelephoneDisplay.of(owner.getTelephone()))")
24	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
25	    @Mapping(target = "householdId", expression = "java(HouseholdId.of(owner.getLastName(), owner.getPostcode()))")
26	    @Mapping(target = "identityKey", expression = "java(IdentityKey.of(owner.getTelephone(), owner.getEmail(), owner.getLastName()))")
27	    @Mapping(target = "membershipNumber", expression = "java(MembershipNumber.of(owner.getCustomerCode(), owner.getRegistrationDate()))")
28	    @Mapping(target = "checkDigit", expression = "java(CheckDigit.of(owner.getCustomerCode()))")
29	    @Mapping(target = "membershipLevel", ignore = true)
30	    @Mapping(target = "membershipPoints", ignore = true)
31	    @Mapping(target = "locality", expression = "java(owner.getCustomerCode() != null ? owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')) : Locality.of(owner.getPostcode(), owner.getCity()))")
32	    @Mapping(target = "timezone", expression = "java(Timezone.of(owner.getCustomerCode() != null ? owner.getCustomerCode().substring(0, owner.getCustomerCode().indexOf('-')) : Locality.of(owner.getPostcode(), owner.getCity())))")
33	    @Mapping(target = "contactPreference", expression = "java(ContactPreference.of(owner.getEmail()))")
34	    @Mapping(target = "ageBand", expression = "java(AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()))")
35	    @Mapping(target = "fiscalYear", expression = "java(FiscalYear.label(owner.getRegistrationDate()))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    Owner toOwner(OwnerDto ownerDto);
39	
40	    @Mapping(target = "id", ignore = true)
41	    @Mapping(target = "pets", ignore = true)
42	    Owner toOwner(OwnerFieldsDto ownerDto);
43	
44	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
45	
46	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
47	
48	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
49	        OwnerPageDto ownerPageDto = new OwnerPageDto();
50	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
51	        ownerPageDto.setPage(ownerPage.getNumber());
52	        ownerPageDto.setSize(ownerPage.getSize());
53	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
54	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
55	        return ownerPageDto;
56	    }
57	}
