1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.slf4j.Logger;
7	import org.slf4j.LoggerFactory;
8	import org.springframework.samples.petclinic.mapper.MembershipLevel;
9	import org.springframework.samples.petclinic.mapper.MembershipNumber;
10	import org.springframework.samples.petclinic.mapper.MembershipPoints;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	public class SaveOwner {
15	
16	    private static final Logger audit = LoggerFactory.getLogger("AUDIT");
17	
18	    private static final AtomicLong EVENT_SEQ = new AtomicLong();
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        ownerRepository.save(owner);
