2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Derives the stable household identifier shared by owners at the same household,
9	 * i.e. having the same last name and postcode (last name compared case-insensitively
10	 * with collapsed whitespace). It is the first 12 hex characters of SHA-256 over
11	 * {@code normalizedLastName + '|' + postcode}, so every owner in one household resolves
12	 * to the same id without any stored state.
13	 */
14	public final class HouseholdId {
15	
16	    private HouseholdId() {
17	    }
18	
19	    public static String of(String lastName, String postcode) {
20	        String key = normalize(lastName) + "|" + normalize(postcode);
21	        try {
22	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
23	            StringBuilder sb = new StringBuilder();
24	            for (int i = 0; i < 6; i++) {
25	                sb.append(String.format("%02x", digest[i]));
26	            }
27	            return sb.toString();
28	        } catch (NoSuchAlgorithmException e) {
29	            throw new IllegalStateException(e);
30	        }
31	    }
32	
33	    private static String normalize(String value) {
34	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
35	    }
36	}
